package policy; import core.*; public final class PolicyValidator{public Diagnostics validate(PolicyDocument doc){Diagnostics d=new Diagnostics();if(doc==null)return d;int idx=0;for(FirewallRule r:doc.rules()){idx++;if(!r.action().matches("ACCEPT|DROP|REJECT|LOG|RETURN"))d.medium("policy.action","unusual action at rule "+idx);if(r.protocol().equals("tcp")&&r.destinationPort().start()==0&&r.destinationPort().end()==65535)d.low("policy.port","tcp rule without destination port at "+idx);if((r.action().equals("ACCEPT")||r.action().equals("LOG"))&&r.source().equals("any")&&r.destination().equals("any")&&r.destinationPort().start()==0)d.medium("policy.broad","broad permissive rule at "+idx);}return d;}}
